// src/components/Dashboard/ProjectView/ProjectHarvestedHours.js
export default function ProjectHarvestedHours({ project }) {
  const label = project ? `${project.intake_number} — ${project.intake_name}` : "";
  return (
    <div className="tab-wrap">
      <div className="tab-section tab-section-yellow">Harvested hours Details</div>
      <div style={{ marginTop: 8 }}>
        {label ? `Welcome to Harvested hours Details for ${label}` : "Welcome to Harvested hours Details"}
      </div>
    </div>
  );
}
